INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FM10VVH5SHX6TK6DMYSR4J9R', 'task', NULL, 'ticket list projection: --fields / --oneline, drop description by default', 'Accepted from feature-request.md FR-1 (clide 2026-06-17 + settled-reach 2026-07-07). ticket list serializes all fields; description is ~81% of the payload (735 KB on a 425-ticket vault, truncated by agent harnesses). Add --fields <csv> projection (JSON stays JSON, narrower rows), --oneline (id<TAB>status<TAB>title human mode), drop description from the default projection with --full to opt back in. Apply the same helper to decisions list for consistency.', 'backlog', 'high', NULL, NULL, NULL, '2026-07-08 06:56:26.505', '2026-07-08 06:56:26.505', NULL, '1ce26df5a125cc68879f8ba7191f79ab', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FM10VVH5SHX6TK6DMYSR4J9R', 'task', NULL, 'ticket list projection: --fields / --oneline, drop description by default', 'Accepted from feature-request.md FR-1 (clide 2026-06-17 + settled-reach 2026-07-07). ticket list serializes all fields; description is ~81% of the payload (735 KB on a 425-ticket vault, truncated by agent harnesses). Add --fields <csv> projection (JSON stays JSON, narrower rows), --oneline (id<TAB>status<TAB>title human mode), drop description from the default projection with --full to opt back in. Apply the same helper to decisions list for consistency.', 'in_progress', 'high', NULL, NULL, NULL, '2026-07-08 06:56:26.505', '2026-07-08 06:57:08.548', NULL, 'e3a9626dae00016c46a8be344584e15b', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FM2BKV2CFG7JHXDMQA7SYBRW', 'bug', NULL, 'integration skill tests escape the sandbox: scope auto-resolve hits the real ~/.claude/skills', 'make test-integration mutates the developer''s HOME: the skill install/status/init tests invoke the binary without overriding HOME, and resolveSkillsRoot auto-resolves to user scope whenever any bundled skill is installed at ~/.claude/skills (true on any dev machine, never in CI). Observed 2026-07-08: six tests fail locally (StatusOnMissing, InstallIsIdempotent, InstallRefusesModified, Doctor_SkillFieldReportsState, Init_WithSkillYes/No) and the run overwrote ~/.claude/skills/pql/SKILL.md with the test binary''s embedded copy. Uninstall is safe (project-scope default, no auto-resolve). Fix: set HOME (and any config env) to a temp dir in the integration run() helper so the suite is hermetic; then these tests gate locally too.', 'backlog', 'high', NULL, NULL, NULL, '2026-07-08 10:03:13.043', '2026-07-08 10:03:13.043', NULL, '10a4256f866ae0408e55808303b5f156', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
